import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def multi_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def test_n(n):
    results = {}
    for k in range(1, 4):
        # x_k = lcm(k, k+1, ..., k+n-1)
        range_k = range(k, k + n)
        x_k = multi_lcm(list(range_k))

        # x_{k+1} = lcm(k+1, k+2, ..., k+n)
        # This requires n numbers starting from k+1.
        # The sequence for x_{k+1} is k+1, ..., k+1+n-1 = k+n
        range_k_plus_1 = range(k + 1, k + 1 + n)
        x_k_plus_1 = multi_lcm(list(range_k_plus_1))

        is_decreasing = x_k_plus_1 <= x_k
        results[k] = {
            "x_k": x_k,
            "x_k+1": x_k_plus_1,
            "decreasing": is_decreasing
        }
    return results

# Test n = 4, 5, 6, 7
