all_results = {}
for n in test_values:
    all_results[n] = test_n(n)
    print(f"--- Results for n = {n} ---")
    for k, res in all_results[n].items():
        print(f"k={k}: x_{k+1} <= x_k? {res['decreasing']}")
        print(f"      x_k = {res['x_k']}")
        print(f"      x_{k+1} = {res['x_k+1']}")

