import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 6
k_values = [1, 2, 3, 4]

results = {}
print("k | x_k | x_{k+1} | Ratio x_{k+1}/x_k | x_{k+1} > x_k?")
print("-" * 50)

for k in k_values:
    # x_k = lcm(k, ..., k+n-1)
    x_k_numbers = list(range(k, k + n))
    x_k = list_lcm(x_k_numbers)

    # x_{k+1} = lcm(k+1, ..., k+n)
    x_k_plus_1_numbers = list(range(k + 1, k + 1 + n))
    x_k_plus_1 = list_lcm(x_k_plus_1_numbers)

    ratio = x_k_plus_1 / x_k
    is_greater = x_k_plus_1 > x_k

    results[k] = (x_k, x_k_plus_1, ratio, is_greater)

    print(f"{k} | {x_k} | {x_k_plus_1} | {ratio} | {is_greater}")

print("\nCalculations stored in results dictionary.")

